@staticmethod
def _parse_datetime(text: str) -> datetime | None:
    """Parse the match start time, preferring Offstage's explicit start block.

    Detail pages contain many unrelated timestamps (news cards, previous
    matches, article dates).  The authoritative match timestamp is rendered
    next to the ``Начало матча`` label, so generic page-wide regexes are only
    a legacy fallback.  This prevents a same-team current card from being
    rejected because an unrelated timestamp happened to appear earlier in
    the page text.
    """
    months = {
        "янв": 1, "фев": 2, "мар": 3, "апр": 4, "мая": 5, "май": 5,
        "июн": 6, "июл": 7, "авг": 8, "сен": 9, "окт": 10, "ноя": 11, "дек": 12,
    }

    def build(hh: str, mm: str, day: str, mon_text: str, year: str) -> datetime | None:
        month = months.get(mon_text.lower()[:3])
        if not month:
            return None
        try:
            return datetime(
                int(year), month, int(day), int(hh), int(mm),
                tzinfo=OffstageAdapter.TIMEZONE,
            )
        except ValueError:
            return None

    # Current/real detail-card shapes observed in Offstage fixtures:
    #   Начало матча\n12:08\n26 авг. 2026
    #   Начало матча\n20:45 1 сент. 2026
    # Keep the search window deliberately short so timestamps from other
    # page sections cannot leak into the match-start parser.
    start_block = re.search(
        r"Начало\s+матча(?P<body>.{0,120})", text, re.I | re.S
    )
    if start_block:
        body = start_block.group("body")
        m = re.search(
            r"(\d{1,2}):(\d{2})\s+(\d{1,2})\s+([А-Яа-яЁё]{3,})\.?\s+(20\d{2})",
            body, re.I,
        )
        if m:
            parsed = build(*m.groups())
            if parsed is not None:
                return parsed

